<?php
if(!defined('ABSPATH'))exit;
function dgs_mgmt_form($op,$year){return '<form method="post" class="dge-form dgm-form" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_management','dgs_management_nonce',true,false).'<input type="hidden" name="action" value="dgs_management"><input type="hidden" name="operation" value="'.esc_attr($op).'"><input type="hidden" name="year" value="'.esc_attr($year).'">';}
function dgs_mgmt_filter_select($name,$label,$items,$selected,$all){return str_replace('<option value="">انتخاب کنید</option>','<option value="">'.esc_html($all).'</option>',dgs_edu_select($name,$label,$items,$selected,false));}
function dgs_mgmt_icon($key){return dgs_portal_icon($key);}
function dgs_mgmt_badge($status){return '<span class="dgm-badge dgm-state-'.esc_attr($status).'">'.dgs_mgmt_icon(array('approved'=>'check','rejected'=>'close','review'=>'clock','referred'=>'refresh')[$status]??'clock').esc_html(dgs_request_states()[$status]??$status).'</span>';}
function dgs_rq_date($raw){if(!$raw||!dgs_record_birth($raw))return ''; $p=explode('-',str_replace('/','-',dgs_edu_digits($raw)));return dgs_att_gregorian((int)$p[0],(int)$p[1],(int)$p[2]);}
function dgs_management_requests($year){if(!dgs_manage_allowed())return '';$type=sanitize_key(dgs_att_get('rq_type','admission'));if(!isset(dgs_request_types()[$type]))$type='admission';$status=sanitize_key(dgs_att_get('rq_status'));$from=dgs_rq_date(dgs_att_get('rq_from'));$to=dgs_rq_date(dgs_att_get('rq_to'));$page=max(1,absint(dgs_att_get('rq_page','1')));$out='<div class="dsp-school dgm-requests">'.dgs_school_title('درخواست‌ها و پیش‌ثبت‌نام‌ها','مدیریت درخواست‌های ثبت‌شده از سوی خانواده‌ها و پیگیری فرایند پذیرش و خدمات آموزشی').'<nav class="dgm-tabs">';foreach(array('admission'=>'پیش‌ثبت‌نام مدرسه','class'=>'رزرو کلاس تقویتی','counseling'=>'مشاوره حضوری') as $key=>$title)$out.='<a '.($key===$type?'aria-current="page"':'').' href="'.esc_url(dgs_school_url('requests',$year,array('rq_type'=>$key))).'">'.dgs_mgmt_icon(array('admission'=>'users','class'=>'classes','counseling'=>'timetable')[$key]).esc_html($title).'</a>';$out.='</nav><a class="dgm-contact-link" href="'.esc_url(dgs_school_url('requests',$year,array('rq_type'=>'contact'))).'">پیام‌های تماس با مدرسه</a><section class="dgm-card"><form method="get" class="dgm-filter" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="requests"><input type="hidden" name="dg_year" value="'.esc_attr($year).'"><input type="hidden" name="rq_type" value="'.esc_attr($type).'">'.dgs_edu_select('rq_status','وضعیت درخواست',array(''=>'همه موارد')+dgs_request_states(),$status,false).'<label>از تاریخ شمسی<input name="rq_from" placeholder="1405-07-01" value="'.esc_attr(dgs_att_get('rq_from')).'"></label><label>تا تاریخ شمسی<input name="rq_to" placeholder="1405-12-29" value="'.esc_attr(dgs_att_get('rq_to')).'"></label><div class="dgm-actions"><button class="dg-btn">'.dgs_mgmt_icon('search').' اعمال فیلتر</button><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_school_url('requests',$year,array('rq_type'=>$type))).'">'.dgs_mgmt_icon('refresh').' پاکسازی</a></div></form></section>';
 if((dgs_att_get('rq_from')&&!$from)||(dgs_att_get('rq_to')&&!$to)||($from&&$to&&$from>$to))return $out.'<p class="dge-error">بازه تاریخ معتبر نیست؛ تاریخ شمسی درست وارد کنید.</p></div>';$q=dgs_request_query($type,$status,$from,$to,$page);$out.='<section class="dgm-card">'.dgs_edu_table_start(array('ردیف','دانش‌آموز / متقاضی','نوع درخواست','پایه / رشته درخواستی','تاریخ ثبت','وضعیت','مشاهده'));foreach($q->posts as $i=>$p){$d=get_post_meta($p->ID,'_dgs_data',true);$d=is_array($d)?$d:array();$state=get_post_meta($p->ID,'_dgs_status',true)?:'new';$url=dgs_school_url('requests',$year,array('rq_type'=>$type,'rq_status'=>$status,'rq_from'=>dgs_att_get('rq_from'),'rq_to'=>dgs_att_get('rq_to'),'rq_page'=>$page,'request_id'=>$p->ID));$out.='<tr '.(absint(dgs_att_get('request_id'))===$p->ID?'class="dgm-selected"':'').'><td>'.esc_html(dgs_fa_digits(($page-1)*10+$i+1)).'</td><td>'.esc_html($d['name']??'—').'</td><td>'.esc_html(dgs_request_types()[$type]).'</td><td>'.esc_html(!empty($d['grade'])?dgs_edu_grade_label($d['grade']).' · '.(dgs_edu_fields()[$d['field']??'']??''):'—').'</td><td>'.esc_html(dgs_fa_digits(dgs_att_jdate(substr($p->post_date,0,10)))).'</td><td>'.dgs_mgmt_badge($state).'</td><td><a class="dgm-view" href="'.esc_url($url).'#dgm-request-detail">'.dgs_mgmt_icon('eye').' مشاهده</a></td></tr>';}$out.='</tbody></table></div>';if(!$q->posts)$out.='<p class="dgm-empty">درخواستی در این بازه ثبت نشده است.</p>';$out.='<nav class="dge-pagination">';foreach(array(-1=>'قبلی',1=>'بعدی') as $step=>$label)if($page+$step>0&&$page+$step<=$q->max_num_pages)$out.='<a href="'.esc_url(dgs_school_url('requests',$year,array('rq_type'=>$type,'rq_status'=>$status,'rq_from'=>dgs_att_get('rq_from'),'rq_to'=>dgs_att_get('rq_to'),'rq_page'=>$page+$step))).'">'.esc_html($label).'</a>';$out.='<span>'.esc_html(dgs_fa_digits($page)).' / '.esc_html(dgs_fa_digits(max(1,$q->max_num_pages))).' · '.esc_html(dgs_fa_digits($q->found_posts)).' درخواست</span></nav></section>';
 $id=absint(dgs_att_get('request_id'));$p=$id?dgs_request_private($id):null;if($id&&!$p)return $out.'<p class="dge-error">درخواست مجاز پیدا نشد.</p></div>';if(!$p&&$q->posts){$p=$q->posts[0];$id=$p->ID;}if(!$p)return $out.'</div>';$d=get_post_meta($id,'_dgs_data',true);$d=is_array($d)?$d:array();$state=get_post_meta($id,'_dgs_status',true)?:'new';$date=dgs_att_jdate(substr($p->post_date,0,10));$review_form=dgs_mgmt_form('request_review',$year).'<input type="hidden" name="request_id" value="'.$id.'"><input type="hidden" name="rq_type" value="'.esc_attr($d['type']??$type).'"><input type="hidden" name="revision" value="'.esc_attr(dgs_request_review_hash($id)).'">';$out.='<section class="dgm-card dgm-request-detail" id="dgm-request-detail"><h3>جزئیات درخواست '.esc_html(dgs_request_types()[$d['type']??'']??'').'</h3><header class="dgm-detail-heading"><div><h2>'.dgs_mgmt_icon('users').esc_html($d['name']??'').'</h2><small>کد درخواست: P-'.esc_html(substr($date,0,4)).'-'.$id.'</small></div><div>'.dgs_mgmt_badge($state).'<small>تاریخ ثبت: '.esc_html(dgs_fa_digits($date.' · '.substr($p->post_date,11,5))).'</small></div></header>'.$review_form.'<div class="dgm-two"><div>'.dgs_record_card('اطلاعات دانش‌آموز / متقاضی',array('نام و نام خانوادگی'=>$d['name']??'','پایه / رشته درخواستی'=>!empty($d['grade'])?dgs_edu_grade_label($d['grade']).' · '.(dgs_edu_fields()[$d['field']??'']??''):'—','مدرسه فعلی'=>$d['prev_school']??'','پایه فعلی'=>$d['current_grade']??'','توضیحات درخواست'=>$d['message']??'')).dgs_record_card('اطلاعات ولی / تماس',array('نام ولی'=>$d['parent_name']??'','شماره تماس'=>$d['phone']??'','نسبت'=>$d['relation']??''));if(($d['type']??'')==='class'&&!empty($d['class_id']))$out.=dgs_record_card('کلاس تقویتی درخواستی',array('عنوان کلاس'=>get_the_title($d['class_id'])));$out.='</div><div><section class="dsr-card"><h3>'.dgs_mgmt_icon('attachment').' مدارک پیوست‌شده</h3><ul class="dgm-documents">';$files=get_post_meta($id,'_dgs_request_files',true);$files=is_array($files)?$files:array();foreach($files as $f){$url=wp_nonce_url(add_query_arg(array('action'=>'dgs_request_file','request_id'=>$id,'file'=>$f['token']),admin_url('admin-post.php')),'dgs_request_file');$out.='<li>'.dgs_mgmt_icon('file').'<span>'.esc_html($f['file_name']).'<small>'.esc_html(size_format($f['file_size'])).'</small></span><a title="دانلود مدرک" aria-label="دانلود مدرک" href="'.esc_url($url).'">'.dgs_mgmt_icon('download').'</a></li>';}$out.='</ul>'.(!$files?'<p class="dgm-empty">مدرکی پیوست نشده است.</p>':'').'</section><section class="dsr-card"><h3>'.dgs_mgmt_icon('edit').' یادداشت مسئول مدرسه</h3><textarea name="note" rows="6" maxlength="4000" placeholder="نتیجه بررسی و اقدامات لازم…">'.esc_textarea(get_post_meta($id,'_dgs_staff_note',true)).'</textarea><small>خصوصی برای مدیریت؛ ارجاع در این نسخه ثبت وضعیت پیگیری است.</small></section></div></div><div class="dgm-actions dgm-request-buttons"><button class="dg-btn" name="status" value="approved">'.dgs_mgmt_icon('check').' تأیید درخواست</button><button class="dg-btn dg-btn-outline" name="status" value="referred">'.dgs_mgmt_icon('send').' پیگیری و ارجاع</button><button class="dg-btn dgm-danger" name="status" value="rejected" data-dge-confirm="درخواست با دلیل واردشده رد شود؟">'.dgs_mgmt_icon('close').' رد درخواست</button><button class="dg-btn dg-btn-outline" name="status" value="review">ذخیره یادداشت / بررسی</button></div></form><p class="dgm-help">تأیید درخواست به معنی ساخت حساب یا دریافت شهریه نیست؛ ثبت نهایی دانش‌آموز از مدیریت آموزشی انجام می‌شود.</p></section></div>';
 return $out;
}
function dgs_os_hidden($ctx){$out='';foreach(array('os_month'=>$ctx['month'],'os_assessment'=>$ctx['assessment'],'os_class'=>$ctx['class']) as $k=>$v)$out.='<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';return $out;}
function dgs_os_mean($rows){$valid=array_filter(array_column($rows,'average'),function($v){return $v!==null;});return $valid?array_sum($valid)/count($valid):null;}
function dgs_os_bar_chart($values){$out='<div class="dgm-bars" role="img" aria-label="میانگین نمرات به تفکیک پایه">';foreach(array(10=>'دهم',11=>'یازدهم',12=>'دوازدهم') as $g=>$label){$v=$values[$g]??null;$out.='<div><div class="dgm-bar-track"><span style="height:'.($v===null?0:round($v/20*100,2)).'%"><b>'.esc_html(dgs_school_number($v,2)).'</b></span></div><strong>پایه '.esc_html($label).'</strong></div>';}return $out.'</div>';}
function dgs_edu_view_oversight($year){if(!dgs_manage_allowed())return '';$ctx=dgs_os_context($_GET,$year);$data=dgs_os_data($ctx);$monthoptions=array();foreach(explode('-',$year) as $y)for($m=1;$m<=12;$m++){$key=sprintf('%04d-%02d',$y,$m);if(dgs_grade_period($key,$year))$monthoptions[$key]=dgs_study_months()[$m].' '.dgs_fa_digits($y);}ksort($monthoptions);$classoptions=dgs_edu_class_options(dgs_edu_classes($year));$out='<div class="dsp-school dgm-oversight" id="dgm-report">'.dgs_school_title('نظارت و انتشار کارنامه','پایش ثبت نمرات، تحلیل عملکرد و آماده‌سازی و انتشار گزارش‌های دوره‌ای').'<section class="dgm-card dgm-tools"><form class="dgm-filter" method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="oversight"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('os_month','ماه گزارش',$monthoptions,$ctx['month']).dgs_edu_select('os_assessment','دوره ارزیابی',array('month'=>'ماهانه','term1'=>'نوبت اول · تجمیع ماه‌ها','term2'=>'نوبت دوم · تجمیع ماه‌ها'),$ctx['assessment']).dgs_mgmt_filter_select('os_class','محدوده',$classoptions,$ctx['class'],'کل مدرسه').'<button class="dg-btn">'.dgs_mgmt_icon('refresh').' به‌روزرسانی گزارش</button></form></section>';
 $mean=dgs_os_mean($data['averages']);$bygrade=array();foreach(array(10,11,12) as $grade)$bygrade[$grade]=dgs_os_mean(array_filter($data['averages'],function($s)use($grade){return (int)$s['grade']===$grade;}));$out.='<div class="dgm-stat-grid">';foreach(array('میانگین کل مدرسه'=>$mean,'میانگین پایه دهم'=>$bygrade[10],'میانگین پایه یازدهم'=>$bygrade[11],'میانگین پایه دوازدهم'=>$bygrade[12]) as $label=>$value)$out.='<article class="dgm-card"><h3>'.dgs_mgmt_icon(strpos($label,'کل')!==false?'education':'users').esc_html($label).'</h3><strong>'.esc_html(dgs_school_number($value,2)).'</strong><small>از نمرات ثبت‌شده بازه انتخابی</small></article>';$out.='</div><div class="dgm-two"><section class="dgm-card"><h3>'.dgs_mgmt_icon('trend').' روند میانگین کل مدرسه</h3>';$series=dgs_school_grade_series($year);$out.=dgs_school_line_chart($series).'</section><section class="dgm-card"><h3>'.dgs_mgmt_icon('grades').' میانگین نمرات به تفکیک پایه</h3>'.dgs_os_bar_chart($bygrade).'</section></div><div class="dgm-status-layout"><aside><section class="dgm-card"><h3>'.dgs_mgmt_icon('info').' نمرات ثبت‌نشده</h3><strong class="dgm-big">'.esc_html(dgs_fa_digits($data['missing'])).'</strong><p>از '.esc_html(dgs_fa_digits($data['expected'])).' نمره مورد انتظار</p>';if($data['unconfigured'])$out.='<p>'.esc_html(dgs_fa_digits($data['unconfigured'])).' دانش‌آموز در کلاس بدون تخصیص درس</p>';$out.='</section><section class="dgm-card"><h3>'.dgs_mgmt_icon('warning').' در معرض افت تحصیلی</h3><strong class="dgm-big">'.esc_html(dgs_fa_digits(count(array_filter($data['averages'],function($s){return $s['average']!==null&&$s['average']<10;})))).'</strong><p>میانگین ثبت‌شده کمتر از ۱۰</p></section></aside><section class="dgm-card"><h3>'.dgs_mgmt_icon('users').' وضعیت ثبت نمرات توسط دبیران</h3>'.dgs_edu_table_start(array('دبیر','درس','پایه‌های تدریس','درصد تکمیل','وضعیت'));foreach($data['teachers'] as $row){$pct=$row['expected']?(int)floor($row['done']/$row['expected']*100):0;$grades=array_map('dgs_edu_grade_label',array_keys($row['grades']));$out.='<tr><td>'.esc_html($row['name']).'</td><td>'.esc_html($row['subject']).'</td><td>'.esc_html(implode('، ',$grades)).'</td><td>'.esc_html(dgs_fa_digits($pct)).'٪</td><td><span class="dgm-badge '.($pct===100?'dgm-complete':'').'">'.dgs_mgmt_icon($pct===100?'check':'clock').($pct===100?'کامل':'در حال تکمیل').'</span></td></tr>';}$out.='</tbody></table></div>'.(!$data['teachers']?'<p class="dgm-empty">تخصیص دبیر و درس وجود ندارد.</p>':'').'</section></div><div class="dgm-two"><section class="dgm-card"><h3>'.dgs_mgmt_icon('edit').' ویرایش نمرات</h3><p class="dgm-help">نمرات ثبت‌شده قابل اصلاح‌اند؛ ثبت نمره تازه از «ثبت و مدیریت نمرات» انجام می‌شود.</p><details class="dgm-tools"><summary>انتخاب کلاس و درس برای ویرایش</summary><form method="get"><input type="hidden" name="dg_tab" value="oversight"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_os_hidden($ctx);$pairs=array();foreach($data['pairs'] as $p)$pairs[$p->class_id.':'.$p->subject_id]=dgs_edu_class_label($data['classes'][$p->class_id]).' · '.$p->subject;$selected=dgs_att_get('os_pair');if(!isset($pairs[$selected]))$selected=(string)array_key_first($pairs);$out.=dgs_edu_select('os_pair','کلاس و درس',$pairs,$selected).'<button class="dg-btn dg-btn-outline">نمایش</button></form></details>'.dgs_mgmt_form('edit_grades',$year).dgs_os_hidden($ctx).'<input type="hidden" name="os_pair" value="'.esc_attr($selected).'">'.dgs_edu_table_start(array('دانش‌آموز','ماه','نمره ثبت‌شده','ویرایش نمره'));$editcount=0;foreach($data['records'] as $r)if($r->class_id.':'.$r->subject_id===$selected&&$editcount<100){$editcount++;$out.='<tr><td>'.esc_html($data['averages'][$r->student_id]['name']).'</td><td>'.esc_html(dgs_fa_digits($r->period)).'</td><td>'.esc_html(dgs_fa_digits($r->score)).'</td><td><input type="hidden" name="os_hashes['.(int)$r->id.']" value="'.esc_attr(dgs_os_grade_hash($r)).'"><input aria-label="نمره '.esc_attr($data['averages'][$r->student_id]['name']).'" name="os_scores['.(int)$r->id.']" type="number" min="0" max="20" step="0.01" required value="'.esc_attr($r->score).'"></td></tr>';}$out.='</tbody></table></div>'.($editcount?'<button class="dg-btn">'.dgs_mgmt_icon('check').' ذخیره تغییرات</button>':'<p class="dgm-empty">نمره‌ای برای ویرایش این کلاس و درس موجود نیست.</p>').'</form></section><section class="dgm-card" id="dgm-rank"><h3>'.dgs_mgmt_icon('trophy').' رتبه‌بندی دانش‌آموزان</h3><form method="get" class="dgm-rank-filter"><input type="hidden" name="dg_tab" value="oversight"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_os_hidden($ctx).dgs_mgmt_filter_select('os_grade','پایه',array(10=>'دهم',11=>'یازدهم',12=>'دوازدهم'),$ctx['grade'],'همه پایه‌ها').dgs_mgmt_filter_select('os_field','رشته',dgs_edu_fields(),$ctx['field'],'همه رشته‌ها').'<button class="dg-btn dg-btn-outline">نمایش</button></form>'.dgs_edu_table_start(array('رتبه','نام و نام خانوادگی','پایه و رشته','میانگین'));$ranked=array_values(array_filter($data['averages'],function($s)use($ctx){return $s['average']!==null&&(!$ctx['grade']||(int)$s['grade']===$ctx['grade'])&&(!$ctx['field']||$s['field']===$ctx['field']);}));usort($ranked,function($a,$b){return $b['average']<=>$a['average'];});$rank=0;$last=null;foreach(array_slice($ranked,0,20) as $i=>$r){if($last===null||abs($last-$r['average'])>.00001)$rank=$i+1;$last=$r['average'];$out.='<tr><td>'.esc_html(dgs_fa_digits($rank)).'</td><td>'.esc_html($r['name']).'</td><td>'.esc_html(dgs_edu_class_label((object)$r)).'</td><td>'.esc_html(dgs_school_number($r['average'],2)).'</td></tr>';}$out.='</tbody></table></div><p class="dgm-help">۲۰ رتبه نخست محدوده انتخابی؛ رتبه مساوی، یکسان است. تا تکمیل نمرات، رتبه‌ها موقت‌اند.</p></section></div><div class="dgm-two"><section class="dgm-card"><h3>'.dgs_mgmt_icon('file').' پیش‌نمایش و انتشار کارنامه</h3><div class="dgm-preview"><div class="dgm-mini-report">'.str_replace('dgs-','dgm-mini-',file_get_contents(DGS_PATH.'assets/portal-logo.svg')).'<b>مدرسه دانشگران</b><span>گزارش عملکرد</span></div><div><strong>'.esc_html(array('month'=>'کارنامه ماهانه','term1'=>'گزارش تجمیعی نوبت اول','term2'=>'گزارش تجمیعی نوبت دوم')[$ctx['assessment']]).'</strong><p>سال '.esc_html(dgs_fa_digits($year)).' · '.esc_html(dgs_fa_digits(count($data['students']))).' دانش‌آموز</p><p>'.esc_html(dgs_fa_digits(count($data['records']))).' نمره ثبت‌شده</p></div></div><button class="dg-btn dg-btn-outline dgm-tools" type="button" data-school-dialog="dgm-preview-dialog">'.dgs_mgmt_icon('eye').' مشاهده پیش‌نمایش</button>'.dgs_mgmt_form('publish',$year).dgs_os_hidden($ctx).'<input type="hidden" name="snapshot" value="'.esc_attr($data['hash']).'"><label class="dgm-checkbox"><input type="checkbox" name="approve" value="1" required>پیش‌نمایش و کامل‌بودن نمرات را بررسی و انتشار را تأیید می‌کنم.</label><button class="dg-btn">'.dgs_mgmt_icon('send').' انتشار کارنامه</button></form><p class="dgm-help">انتشار فقط در صورت تکمیل همه نمرات مورد انتظار انجام می‌شود.</p></section><section class="dgm-card"><h3>'.dgs_mgmt_icon('file').' خروجی‌های گزارش</h3><p>محدوده: '.esc_html($ctx['class']&&isset($data['classes'][$ctx['class']])?dgs_edu_class_label($data['classes'][$ctx['class']]):'کل مدرسه').'</p><div class="dgm-actions"><button class="dg-btn dgm-tools" type="button" data-school-print="dgm-report">'.dgs_mgmt_icon('printer').' چاپ / ذخیره PDF</button><a class="dg-btn dg-btn-outline dgm-tools" href="'.esc_url(wp_nonce_url(add_query_arg(array('action'=>'dgs_oversight_export','year'=>$year,'os_month'=>$ctx['month'],'os_assessment'=>$ctx['assessment'],'os_class'=>$ctx['class']),admin_url('admin-post.php')),'dgs_oversight_export')).'">خروجی Excel</a></div><p class="dgm-help">میانگین‌ها ساده و بدون ضریب‌اند و نمرات پیش‌نویس را برای نظارت شامل می‌شوند. روند مدرسه فقط نمرات منتشرشده ماهانه است. تجمیع نوبتی میانگین ماه‌های بازه است؛ کارنامه رسمی ضریب‌دار نیست.</p></section></div><dialog class="dsp-dialog" id="dgm-preview-dialog"><button class="dsp-dialog-close" data-school-close type="button">×</button><h3>پیش‌نمایش نمرات بازه انتخابی</h3>'.dgs_edu_table_start(array('دانش‌آموز','میانگین ساده','تعداد نمره'));foreach(array_slice($data['averages'],0,100) as $s)$out.='<tr><td>'.esc_html($s['name']).'</td><td>'.esc_html(dgs_school_number($s['average'],2)).'</td><td>'.esc_html(dgs_fa_digits($s['count'])).'</td></tr>';return $out.'</tbody></table></div><p class="dgm-help">حداکثر ۱۰۰ دانش‌آموز در پیش‌نمایش؛ خروجی اکسل شامل نمرات محدوده است.</p></dialog></div>';
}
add_action('wp_enqueue_scripts',function(){if(!dgs_is_role_portal()||!in_array(dgs_portal_tab(),array('requests','oversight'),true))return;wp_add_inline_style('dgs-school-panels',file_get_contents(DGS_PATH.'assets/management-pages.css'));},40);
